<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>POS & Product Tools | Goodlucks Goods</title><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#252A34"><style>
:root{--teal:#08D9D6;--pink:#FF2E63;--dark:#252A34;--grey:#EAEAEA;--bg:#f6f7f8;--muted:#65707d;--line:#e2e6ea}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--dark);font:14px/1.45 Arial,Helvetica,sans-serif}.top{background:var(--dark);color:white;padding:14px 20px;display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap;border-bottom:3px solid var(--teal)}.brand{display:flex;align-items:center;gap:13px}.brand img{width:138px;max-height:50px;object-fit:contain;background:white;border-radius:5px;padding:4px}.brand strong{display:block;font-size:14px}.brand small{display:block;color:#cbd3dc;font-size:11px;margin-top:2px}.top-actions{display:flex;gap:8px}.shell{max-width:1440px;margin:auto;padding:18px}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:16px}.tab,.btn{border:1px solid var(--line);background:white;border-radius:9px;padding:10px 13px;color:var(--dark);font:700 12px Arial,sans-serif;cursor:pointer;text-decoration:none;display:inline-flex;gap:7px;align-items:center;justify-content:center}.tab.active,.btn.primary{background:var(--dark);color:white;border-color:var(--dark)}.btn.teal{background:var(--teal);color:var(--dark);border-color:var(--teal)}.btn.danger{color:#c6284b;background:#fff2f5;border-color:#ffd1dc}.btn:disabled{opacity:.5;cursor:not-allowed}.panel{background:white;border:1px solid var(--line);border-radius:14px;padding:18px;margin-bottom:14px}.panel h2,.panel h3{margin:0 0 5px}.sub{color:var(--muted);font-size:12px;margin:0 0 14px}.grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:14px}.span-3{grid-column:span 3}.span-4{grid-column:span 4}.span-5{grid-column:span 5}.span-6{grid-column:span 6}.span-7{grid-column:span 7}.span-8{grid-column:span 8}.span-9{grid-column:span 9}.span-12{grid-column:span 12}.field{display:flex;flex-direction:column;gap:5px;min-width:0}.field label{font-size:11px;font-weight:800;color:#4a5562}.field input,.field select,.field textarea,input,select,textarea{font:13px Arial,sans-serif}.field input,.field select,.field textarea{width:100%;border:1px solid #d8dee5;border-radius:8px;padding:10px;background:#fff;color:var(--dark);outline:none}.field textarea{min-height:88px;resize:vertical}.field input:focus,.field select:focus,.field textarea:focus{border-color:#08bdbb;box-shadow:0 0 0 3px #08d9d620}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.between{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.muted{color:var(--muted);font-size:11px}.notice{border-radius:9px;padding:11px 13px;margin:0 0 13px;background:#effaf9;border:1px solid #b7eeeb;color:#155e5b;font-size:12px}.notice.error{background:#fff2f5;border-color:#ffd1dc;color:#9e163a}.notice:empty{display:none}.catalog-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;max-height:390px;overflow:auto}.product-pick{display:flex;align-items:center;gap:9px;border:1px solid var(--line);border-radius:9px;padding:9px;min-width:0}.product-pick img{width:55px;height:55px;object-fit:cover;border-radius:7px;background:#f0f2f3}.product-pick .name{font-weight:700;font-size:12px;display:block}.product-pick .price{font-size:11px;color:#48515c;margin-top:3px}.product-pick button{margin-left:auto;flex-shrink:0}.cart-table,.data-table{width:100%;border-collapse:collapse;font-size:12px}.cart-table th,.data-table th{text-align:left;font-size:10px;text-transform:uppercase;color:#67717c;background:#f1f4f5;padding:9px}.cart-table td,.data-table td{padding:9px;border-bottom:1px solid #edf0f2;vertical-align:top}.cart-table input{width:84px;padding:7px;border:1px solid #d8dee5;border-radius:6px}.totals{max-width:380px;margin-left:auto}.total-row{display:flex;justify-content:space-between;gap:16px;padding:5px 0;font-size:12px}.total-row.grand{font-size:16px;font-weight:800;border-top:1px solid var(--line);padding-top:10px;margin-top:4px}.pill{display:inline-block;background:#eaf9f8;color:#0a6562;border-radius:99px;padding:4px 8px;font-size:10px;font-weight:800}.pill.pink{background:#fff0f4;color:#b21e44}.empty{padding:28px 12px;text-align:center;color:var(--muted);font-size:12px}.table-wrap{overflow-x:auto}.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.filters input,.filters select{border:1px solid #d8dee5;border-radius:8px;padding:9px;background:#fff;font-size:12px}.tag{display:inline-flex;background:#eaf0f7;color:#344255;border-radius:99px;padding:5px 8px;margin:3px;font-size:11px}.detail-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{background:#f7f9fa;border-radius:9px;padding:12px}.metric small{display:block;color:var(--muted);font-size:10px}.metric strong{display:block;font-size:17px;margin-top:3px}.modal{position:fixed;inset:0;background:#10151dcc;z-index:1000;display:flex;align-items:center;justify-content:center;padding:14px}.modal-card{width:min(760px,100%);max-height:90vh;overflow:auto;background:white;border-radius:14px;padding:18px}.hidden{display:none!important}.checkbox{display:flex;gap:8px;align-items:center;font-size:12px}.checkbox input{width:auto}.mini{font-size:10px}.foot{color:#838b95;font-size:10px;text-align:center;padding:12px}.status{font-weight:800}.status.paid{color:#087e78}.status.partial{color:#976400}.status.pending{color:#bb2449}@media(max-width:850px){.span-3,.span-4,.span-5,.span-6,.span-7,.span-8,.span-9{grid-column:span 12}.shell{padding:10px}.panel{padding:13px}.catalog-list{grid-template-columns:1fr}.detail-grid{grid-template-columns:1fr}.brand img{width:110px}}.manual-item-form input{min-width:0;min-height:46px;font-size:16px;padding:12px 13px}.manual-item-form .field:nth-child(2),.manual-item-form .field:nth-child(3){min-width:0}@media(max-width:700px){#manualForm{grid-template-columns:minmax(0,1fr)!important;gap:12px}#manualForm>.field,#manualForm>.span-12{grid-column:1/-1!important}#manualForm input{min-height:48px;font-size:16px;padding:12px 14px}}@media print{.top,.tabs,.actions,.no-print{display:none!important}body{background:white}.shell{padding:0}.panel{border:0}}

