</style></head><body>
<header class="top"><div class="brand"><img src="/goodlucks-goods-logo.svg" alt="Goodlucks Goods"><div><strong>POS & Product Tools</strong><small>Goodlucks Goods · Existing admin session</small></div></div><div class="top-actions"><a class="btn" href="/admin">Back to Admin Dashboard</a><button class="btn danger" id="logout">Log out</button></div></header>
<div class="shell"><nav class="tabs" id="tabs"><button class="tab active" data-tab="sale">New Sale / POS</button><button class="tab" data-tab="sales">Sales & Payments</button><button class="tab" data-tab="orders">Import WhatsApp Orders</button></nav><div id="notice" class="notice"></div><main id="view"></main><div class="foot">Goodlucks Goods · Financial changes are recorded in the audit history. Receipt links are read-only and can be revoked.</div></div>
<div id="modal" class="modal hidden"><div class="modal-card"><div class="between"><h2 id="modalTitle">Details</h2><button class="btn" data-close-modal>Close</button></div><div id="modalBody"></div></div></div>
<script>
const API='/api'; const CURRENCY='GH₵';const pendingPaymentKeys=new Map();let tab='sale';let catalogue=[];let allProducts=[];let categories=[];let cart=[];let sales=[];let orders=[];let drafts=[];let selectedProductId='';let selectedDraftId='';let selectedSubcategoryId='';let activeSale=null;let lastReceiptUrl='';let draftImages=[];
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=v=>CURRENCY+' '+Number(v||0).toLocaleString('en-GH',{minimumFractionDigits:2,maximumFractionDigits:2});const key=()=>('glg-'+(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2))).slice(0,96);
async function api(path,opts={}){const headers=new Headers(opts.headers||{});headers.set('Accept','application/json');if(opts.body&&!(opts.body instanceof FormData))headers.set('Content-Type','application/json');const r=await fetch(API+path,{...opts,headers,credentials:'include'});let d={};try{d=await r.json()}catch(_){d={message:'Unexpected server response.'}}if(!r.ok||d.success===false)throw new Error(d.message||`Request failed (${r.status})`);return d}
function message(text,isError=false){const n=$('#notice');n.textContent=text||'';n.classList.toggle('error',!!isError);if(text)window.scrollTo({top:0,behavior:'smooth'});}
function statusLabel(s){return ({paid:'Fully Paid',partial:'Partially Paid',pending:'Pending Payment'})[s]||s||'—'}
function localDateTimeValue(){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Accra',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const p=Object.fromEntries(parts.filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`}
function receiptShareText(sale,url){const raw=String(sale?.customerName||'').trim();const firstName=raw.split(/\s+/).filter(Boolean)[0]||'there';const status=statusLabel(sale?.paymentStatus);return `Hi ${firstName}, check out your order receipt and payment status from Goodlucks Goods: ${url}\nPayment status: ${status}\n\nThank you for shopping with Goodlucks Goods.`}
function setTab(t){tab=t;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));message('');render();}
$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)setTab(b.dataset.tab)});
$('#logout').addEventListener('click',async()=>{try{await api('/admin/logout',{method:'POST',body:JSON.stringify({})})}catch(_){}location.href='/admin-login'});
function loadBase(){return Promise.all([api('/admin/products'),api('/categories')]).then(([p,c])=>{allProducts=p.products||[];catalogue=allProducts.filter(x=>x.publicationStatus!=='draft');categories=c.categories||[]})}
function categoryOptions(selected=''){return '<option value="">Choose category…</option>'+categories.map(c=>`<option value="${esc(c.slug)}" ${c.slug===selected?'selected':''}>${esc(c.name)}</option>`).join('')}
function subcategoryList(){return categories.flatMap(c=>(c.subcategories||[]).map(s=>({...s,parentCategorySlug:c.slug,parentCategoryName:c.name}))) }
function render(){if(tab==='sale')renderSale();else if(tab==='sales')renderSales();else if(tab==='orders')renderOrders();}
function cartTotal(){const subtotal=cart.reduce((t,i)=>t+Math.round(Number(i.unitPrice||0)*100)*Number(i.quantity||1),0)/100;const discount=Math.max(0,Number($('#saleDiscount')?.value||0));const delivery=Math.max(0,Number($('#saleDelivery')?.value||0));return {subtotal,discount,delivery,total:Math.max(0,subtotal-discount+delivery)}}
function renderSale(){
 $('#view').innerHTML=`<div class="grid"><section class="span-7"><div class="panel"><div class="between"><div><h2>Start a sale</h2><p class="sub">Search the catalogue or add an item manually. Manual items will not create public products.</p></div><span class="pill">POS</span></div><div class="field"><label>Search existing website products</label><input id="productSearch" placeholder="Search beds, wardrobes, sofas…" autocomplete="off"></div><div id="catalogResults" class="catalog-list" style="margin-top:10px"><div class="empty">Type at least 2 letters to search the catalogue.</div></div></div><div class="panel"><h3>Add a manual item</h3><p class="sub">For custom furniture, special orders, and products not listed online.</p><form id="manualForm" class="grid manual-item-form"><div class="field span-6"><label>Product name *</label><input name="productName" required maxlength="255" placeholder="e.g. Custom 3-seater sofa"></div><div class="field span-3"><label>Quantity</label><input name="quantity" type="number" min="1" max="10000" value="1" required></div><div class="field span-3"><label>Unit price (GH₵)</label><input name="unitPrice" type="number" min="0" step="0.01" required></div><div class="field span-6"><label>Optional product URL for review</label><input name="productUrl" type="url" placeholder="https://shop.goodlucks.co/product/…"></div><div class="field span-6"><label>Item details (optional)</label><input name="description" placeholder="Colour, fabric, custom measurements…"></div><div class="span-12 row" style="align-items:end"><button class="btn teal" type="submit">Add manual item</button></div></form></div></section><section class="span-5"><div class="panel"><div class="between"><h2>Sale items</h2><button class="btn" id="clearCart">Clear</button></div><div id="cartArea"></div><div class="grid" style="margin-top:14px"><div class="field span-6"><label>Discount (GH₵)</label><input id="saleDiscount" type="number" min="0" step="0.01" value="0"></div><div class="field span-6"><label>Delivery fee (GH₵)</label><input id="saleDelivery" type="number" min="0" step="0.01" value="0"></div></div><div class="totals" id="totals" style="margin-top:12px"></div></div></section><section class="span-12"><div class="panel"><h2>Customer & payment details</h2><p class="sub">All amounts are recalculated and validated by the server. Payment entries become permanent payment-history records.</p><form id="saleForm" class="grid"><div class="field span-3"><label>Sales channel</label><select name="channel"><option value="walk_in">Walk-in</option><option value="whatsapp">WhatsApp</option><option value="website">Website</option><option value="manual">Manual</option></select></div><div class="field span-3"><label>Customer name</label><input name="customerName" maxlength="150" placeholder="Customer name"></div><div class="field span-3"><label>Customer phone</label><input name="customerPhone" maxlength="50" placeholder="Phone / WhatsApp"></div><div class="field span-3"><label>Customer email</label><input name="customerEmail" type="email" maxlength="255" placeholder="Optional email"></div><div class="field span-4"><label>Delivery city / location</label><input name="deliveryLocation" maxlength="255" placeholder="Optional delivery location"></div><div class="field span-4"><label>Delivery address / landmark</label><input name="deliveryAddress" maxlength="2000" placeholder="Optional address"></div><div class="field span-4"><label>Sale notes</label><input name="notes" maxlength="3000" placeholder="Optional notes"></div><div class="field span-4"><label>Actual transaction date &amp; time</label><input name="transactionAt" id="transactionAt" type="datetime-local" required></div><div class="field span-3"><label>Initial payment (GH₵)</label><input name="initialPayment" type="number" min="0" step="0.01" value="0"></div><div class="field span-3"><label>Initial payment method</label><select name="initialPaymentMethod"><option value="cash">Cash</option><option value="mobile_money">Mobile Money</option><option value="bank_transfer">Bank transfer</option><option value="card">Card (record only)</option><option value="other">Other</option></select></div><div class="field span-3"><label>Payment reference</label><input name="initialPaymentReference" maxlength="255" placeholder="Optional reference"></div><div class="field span-3" style="justify-content:end"><button class="btn primary" type="submit">Save Sale & Generate Receipt</button></div></form><div id="saleResult" style="margin-top:12px"></div></div></section></div>`;
 renderCart();$('#transactionAt').value=localDateTimeValue();let timer;$('#productSearch').addEventListener('input',e=>{clearTimeout(timer);const q=e.target.value.trim();timer=setTimeout(()=>searchProducts(q),220)});
 $('#manualForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const nm=String(f.get('productName')||'').trim();const price=Number(f.get('unitPrice'));const qty=Number(f.get('quantity'));if(!nm||!Number.isFinite(price)||price<0||!Number.isInteger(qty)||qty<1){message('Enter a valid manual item, quantity, and price.',true);return}cart.push({productId:null,productName:nm,description:String(f.get('description')||''),productUrl:String(f.get('productUrl')||''),quantity:qty,unitPrice:price});e.target.reset();e.target.elements.quantity.value='1';e.target.elements.unitPrice.value='';renderCart();message('Manual item added to this sale.');});
 $('#saleForm').addEventListener('submit',saveSale);$('#clearCart').addEventListener('click',()=>{cart=[];renderCart()});['saleDiscount','saleDelivery'].forEach(id=>$('#'+id).addEventListener('input',updateTotals));
}
async function searchProducts(q){const box=$('#catalogResults');if(!box)return;if(q.length<2){box.innerHTML='<div class="empty">Type at least 2 letters to search the catalogue.</div>';return}box.innerHTML='<div class="empty">Searching…</div>';try{const d=await api('/admin/pos/products?q='+encodeURIComponent(q));box.innerHTML=(d.products||[]).map(p=>`<div class="product-pick"><img src="${esc(p.image||'/favicon.png')}" alt=""><div style="min-width:0"><span class="name">${esc(p.name)}</span><span class="price">${fmt(p.price)} · ${esc((p.stockStatus||'').replaceAll('_',' '))}</span></div><button class="btn teal" data-add-product="${esc(p.id)}">Add</button></div>`).join('')||'<div class="empty">No published catalogue products matched that search.</div>'}catch(e){box.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
$('#view').addEventListener('click',e=>{const b=e.target.closest('[data-add-product]');if(b){const p=catalogue.find(x=>String(x.id)===String(b.dataset.addProduct));if(!p){api('/admin/pos/products?q='+encodeURIComponent('')).catch(()=>{});message('Reload the page and try that product again.',true);return}const old=cart.find(i=>String(i.productId)===String(p.id));if(old)old.quantity++;else cart.push({productId:p.id,productReference:'PROD-'+p.id,productName:p.name,quantity:1,unitPrice:Number(p.discountPrice??p.price),description:'',productUrl:''});renderCart();}});
function renderCart(){const box=$('#cartArea');if(!box)return;if(!cart.length){box.innerHTML='<div class="empty">Add a catalogue product or enter a manual item to begin.</div>'}else{box.innerHTML=`<div class="table-wrap"><table class="cart-table"><thead><tr><th>Item</th><th>Qty</th><th>Unit price</th><th>Total</th><th></th></tr></thead><tbody>${cart.map((i,n)=>`<tr><td><strong>${esc(i.productName)}</strong><div class="muted">${i.productId?'Catalogue product':'Manual item'}</div></td><td><input type="number" min="1" max="10000" value="${esc(i.quantity)}" data-cart-qty="${n}"></td><td><input type="number" min="0" step="0.01" value="${esc(i.unitPrice)}" data-cart-price="${n}"></td><td><strong>${fmt(Number(i.quantity)*Number(i.unitPrice))}</strong></td><td><button class="btn danger" data-remove-cart="${n}">×</button></td></tr>`).join('')}</tbody></table></div>`;box.querySelectorAll('[data-cart-qty]').forEach(el=>el.addEventListener('change',()=>{const n=+el.dataset.cartQty;cart[n].quantity=Math.max(1,Math.min(10000,parseInt(el.value)||1));renderCart()}));box.querySelectorAll('[data-cart-price]').forEach(el=>el.addEventListener('change',()=>{const n=+el.dataset.cartPrice;cart[n].unitPrice=Math.max(0,Number(el.value)||0);renderCart()}));box.querySelectorAll('[data-remove-cart]').forEach(el=>el.addEventListener('click',()=>{cart.splice(+el.dataset.removeCart,1);renderCart()}));}updateTotals();}
function updateTotals(){const t=cartTotal();const box=$('#totals');if(box)box.innerHTML=`<div class="total-row"><span>Subtotal</span><strong>${fmt(t.subtotal)}</strong></div><div class="total-row"><span>Discount</span><strong>−${fmt(t.discount)}</strong></div><div class="total-row"><span>Delivery</span><strong>${fmt(t.delivery)}</strong></div><div class="total-row grand"><span>Total due</span><strong>${fmt(t.total)}</strong></div>`;}
async function saveSale(e){e.preventDefault();if(!cart.length){message('Add at least one item before saving the sale.',true);return}const f=new FormData(e.target);const data=Object.fromEntries(f.entries());data.items=cart.map(i=>({...i,unitPrice:Number(i.unitPrice),quantity:Number(i.quantity)}));data.discount=Number($('#saleDiscount').value||0);data.deliveryFee=Number($('#saleDelivery').value||0);data.initialPayment=Number(data.initialPayment||0);data.requestKey=key();try{const b=e.submitter;b.disabled=true;b.textContent='Saving…';const r=await api('/admin/pos/sales',{method:'POST',body:JSON.stringify(data)});activeSale=r.sale;lastReceiptUrl=r.receiptUrl||'';cart=[];renderCart();$('#saleResult').innerHTML=`<div class="notice">Sale <strong>${esc(r.sale.reference)}</strong> saved. Amount due: <strong>${fmt(r.sale.total)}</strong>. Payment status: <strong>${esc(statusLabel(r.sale.paymentStatus))}</strong>.<div class="row" style="margin-top:9px"><a class="btn teal" href="${esc(lastReceiptUrl||'#')}" target="_blank" rel="noopener">Open customer receipt</a><button class="btn" id="copyReceipt">Copy receipt link</button><a class="btn" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(receiptShareText(r.sale,lastReceiptUrl))}">Share on WhatsApp</a></div><div class="muted" style="margin-top:6px;overflow-wrap:anywhere">${esc(lastReceiptUrl)}</div></div>`;$('#copyReceipt')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(lastReceiptUrl);message('Receipt link copied.')}catch(_){message(lastReceiptUrl)}});e.target.reset();$('#transactionAt').value=localDateTimeValue();$('#saleDiscount').value='0';$('#saleDelivery').value='0';message('Sale saved and receipt created.');}catch(err){message(err.message,true)}finally{if(e.submitter){e.submitter.disabled=false;e.submitter.textContent='Save Sale & Generate Receipt'}}}
async function renderSales(){ $('#view').innerHTML=`<section class="panel"><h2>Sales history & payments</h2><p class="sub">Search by receipt, customer or phone. Payment history is append-only; do not re-enter a payment already recorded.</p><div class="filters"><input id="salesQ" placeholder="Reference, customer, phone"><select id="salesChannel"><option value="">All channels</option><option value="website">Website</option><option value="whatsapp">WhatsApp</option><option value="walk_in">Walk-in</option><option value="manual">Manual</option></select><select id="salesStatus"><option value="">All payment statuses</option><option value="pending">Pending Payment</option><option value="partial">Partially Paid</option><option value="paid">Fully Paid</option></select><input id="salesFrom" type="date"><input id="salesTo" type="date"><button class="btn primary" id="filterSales">Apply filters</button><button class="btn" id="refreshSales">Refresh</button></div><div id="salesTable" class="empty">Loading sales…</div></section><section class="panel"><div class="between"><div><h3>Selected sale</h3><p class="sub">Select View to see item snapshots, payment entries, audit log, and receipt-link controls.</p></div><span id="selectedSaleRef" class="pill">None selected</span></div><div id="saleDetail" class="empty">No sale selected.</div></section>`;
 $('#filterSales').onclick=loadSales;$('#refreshSales').onclick=loadSales;$('#salesQ').addEventListener('keydown',e=>{if(e.key==='Enter')loadSales()});await loadSales(); }
async function loadSales(){const params=new URLSearchParams();[['q','salesQ'],['channel','salesChannel'],['status','salesStatus'],['from','salesFrom'],['to','salesTo']].forEach(([k,id])=>{const v=$('#'+id)?.value;if(v)params.set(k,v)});$('#salesTable').innerHTML='<div class="empty">Loading…</div>';try{const d=await api('/admin/pos/sales?'+params.toString());sales=d.sales||[];$('#salesTable').innerHTML=sales.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Reference / Date</th><th>Customer</th><th>Channel</th><th>Total</th><th>Balance</th><th>Payment</th><th>Receipt link</th><th>Sale</th></tr></thead><tbody>${sales.map(s=>`<tr><td><strong>${esc(s.reference)}</strong><div class="muted">${esc(s.transactionAt||s.createdAt)}</div></td><td>${esc(s.customerName||'Walk-in')}<div class="muted">${esc(s.customerPhone||'')}</div></td><td>${esc(s.channel.replaceAll('_',' '))}</td><td>${fmt(s.total)}</td><td>${fmt(s.balance)}</td><td><span class="status ${esc(s.paymentStatus)}">${esc(statusLabel(s.paymentStatus))}</span></td><td><span class="pill ${s.receiptActive?'':'pink'}">${s.receiptActive?'Active':'Revoked'}</span><div class="row" style="gap:5px;flex-wrap:wrap;margin-top:6px">${s.receiptUrl?`<button class="btn" data-copy-sale-url="${esc(s.id)}">Copy Link</button><a class="btn" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(receiptShareText(s,s.receiptUrl))}">Share</a><button class="btn danger" data-row-receipt-action="revoke" data-id="${esc(s.id)}">Revoke</button>`:`<button class="btn teal" data-row-regenerate="${esc(s.id)}">Generate / Replace</button>`}</div>${s.receiptActive&&!s.receiptUrl?'<div class="muted">Generate once to save this link for future use.</div>':''}</td><td><button class="btn" data-view-sale="${esc(s.id)}">View</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No sales found for these filters.</div>';}catch(e){$('#salesTable').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
$('#view').addEventListener('click',async e=>{const b=e.target.closest('[data-view-sale]');if(b)await viewSale(b.dataset.viewSale);});
async function viewSale(id){try{const d=await api('/admin/pos/sales/'+encodeURIComponent(id));activeSale=d.sale;$('#selectedSaleRef').textContent=d.sale.reference;$('#saleDetail').innerHTML=`<div class="detail-grid"><div class="metric"><small>Total amount due</small><strong>${fmt(d.sale.total)}</strong></div><div class="metric"><small>Total paid</small><strong>${fmt(d.sale.amountPaid)}</strong></div><div class="metric"><small>Outstanding balance</small><strong>${fmt(d.sale.balance)}</strong></div></div><div class="row actions" style="margin:12px 0"><button class="btn teal" data-payment="${esc(d.sale.id)}" ${Number(d.sale.balance)<=0?'disabled':''}>Record payment / update status</button><button class="btn" data-adjust-sale="${esc(d.sale.id)}">Adjust discount / delivery</button><button class="btn" data-regenerate="${esc(d.sale.id)}">Generate / replace receipt link</button>${d.sale.receiptActive?`<button class="btn danger" data-receipt-action="revoke" data-id="${esc(d.sale.id)}">Revoke link</button>`:`<button class="btn" data-receipt-action="reinstate" data-id="${esc(d.sale.id)}">Reinstate link</button>`}<button class="btn" data-sale-audit="${esc(d.sale.id)}">View audit</button></div><h3 style="margin:15px 0 7px">Sale items</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Item</th><th>Qty</th><th>Unit price</th><th>Line total</th><th>Review URL</th></tr></thead><tbody>${(d.sale.items||[]).map(i=>`<tr><td><strong>${esc(i.productName)}</strong><div class="muted">${esc(i.description||'')}</div></td><td>${esc(i.quantity)}</td><td>${fmt(i.unitPrice)}</td><td>${fmt(i.lineTotal)}</td><td>${i.productUrl?'<span class="pill">Available</span>':'<span class="muted">No link</span>'}</td></tr>`).join('')}</tbody></table></div><h3 style="margin:15px 0 7px">Payments</h3>${(d.sale.payments||[]).length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th><th>Notes</th><th>Correction</th></tr></thead><tbody>${d.sale.payments.map(p=>`<tr><td>${esc(p.receivedAt)}</td><td>${esc(p.method)}</td><td>${esc(p.reference||'')}</td><td>${fmt(p.amount)}</td><td>${esc(p.notes||'')}</td><td>${Number(p.amount)>0&&!p.reversalOf&&!(d.sale.payments||[]).some(v=>String(v.reversalOf)===String(p.id))?`<button class="btn danger" data-reverse-payment="${esc(d.sale.id)}" data-payment-id="${esc(p.id)}">Reverse</button>`:'<span class="muted">—</span>'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No payment has been recorded.</div>'}<div id="saleActionResult" style="margin-top:12px"></div>`; }catch(e){message(e.message,true)}}
async function generateReceiptForSale(id){try{const r=await api(`/admin/pos/sales/${encodeURIComponent(id)}/receipt/regenerate`,{method:'POST',body:JSON.stringify({reason:'Receipt link generated or replaced from Sales History'})});const url=r.receiptUrl;message('Receipt link saved for this sale.');await loadSales();await viewSale(id);const shareSale=activeSale||sales.find(s=>String(s.id)===String(id))||{};const shareText=receiptShareText(shareSale,url);const result=document.querySelector('#saleActionResult');if(result)result.innerHTML=`<div class="notice">Active receipt link saved. The previous link, if any, is now invalid.<br><a target="_blank" rel="noopener" href="${esc(url)}">Open receipt</a><div class="muted" style="overflow-wrap:anywhere">${esc(url)}</div><div class="row" style="margin-top:8px"><button class="btn" id="copyReplacement">Copy Link</button><button class="btn teal" id="shareReplacement">Share</button><a class="btn" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(shareText)}">WhatsApp</a></div></div>`;document.querySelector('#copyReplacement')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(url);message('Receipt link copied.')}catch(_){window.prompt('Copy receipt link:',url)}});document.querySelector('#shareReplacement')?.addEventListener('click',async()=>{try{if(navigator.share)await navigator.share({text:shareText});else window.open(`https://wa.me/?text=${encodeURIComponent(shareText)}`,'_blank','noopener');}catch(err){if(err?.name!=='AbortError')message('Sharing was not completed.',true)}});}catch(err){message(err.message,true)}}
$('#view').addEventListener('click',async e=>{const copyRow=e.target.closest('[data-copy-sale-url]');if(copyRow){const sale=sales.find(x=>String(x.id)===String(copyRow.dataset.copySaleUrl));if(!sale?.receiptUrl){message('No active saved receipt link. Generate / Replace it first.',true);return}try{await navigator.clipboard.writeText(sale.receiptUrl);message('Receipt link copied.')}catch(_){window.prompt('Copy receipt link:',sale.receiptUrl)}return}const rowRegen=e.target.closest('[data-row-regenerate]');if(rowRegen){await generateReceiptForSale(rowRegen.dataset.rowRegenerate);return}const rowAction=e.target.closest('[data-row-receipt-action]');if(rowAction){try{await api(`/admin/pos/sales/${rowAction.dataset.id}/receipt/${rowAction.dataset.rowReceiptAction}`,{method:'POST',body:JSON.stringify({reason:'Receipt link revoked from Sales History row'})});message('Receipt link revoked. The link no longer opens.');await loadSales();if(activeSale&&String(activeSale.id)===String(rowAction.dataset.id))await viewSale(rowAction.dataset.id)}catch(err){message(err.message,true)}return}const pay=e.target.closest('[data-payment]');if(pay){const id=pay.dataset.payment;pay.disabled=true;const amount=prompt('Payment amount in GH₵ (outstanding balance: '+activeSale.balance+')');if(amount===null){pay.disabled=false;return}const method=prompt('Payment method: cash, mobile_money, bank_transfer, card, other','cash');if(method===null){pay.disabled=false;return}const ref=prompt('Payment reference (optional)','')||'';const notes=prompt('Payment notes (optional)','')||'';const fingerprint=JSON.stringify({amount:String(amount).trim(),method,ref,notes});const paymentKey=id+':'+fingerprint;if(!pendingPaymentKeys.has(paymentKey))pendingPaymentKeys.set(paymentKey,key());try{const r=await api(`/admin/pos/sales/${id}/payments`,{method:'POST',body:JSON.stringify({amount,method,reference:ref,notes,requestKey:pendingPaymentKeys.get(paymentKey)})});pendingPaymentKeys.delete(paymentKey);message(r.duplicate?'This payment was already recorded; no duplicate was added.':'Payment recorded; previous payments were preserved.');await viewSale(id);await loadSales();}catch(err){message(err.message+' If the connection failed after saving, retry with the same details to avoid a duplicate payment.',true)}finally{if(pay.isConnected)pay.disabled=false}}
 const rev=e.target.closest('[data-reverse-payment]');if(rev){const reason=prompt('Reason for reversing this payment (required):');if(reason===null)return;if(!reason.trim()){message('A reversal reason is required.',true);return}if(!confirm('Record a reversal entry? The original payment will remain in history.'))return;try{await api(`/admin/pos/sales/${rev.dataset.reversePayment}/payments/${rev.dataset.paymentId}/reverse`,{method:'POST',body:JSON.stringify({reason:reason.trim()})});message('Reversal recorded; the original payment remains in the payment history.');await viewSale(rev.dataset.reversePayment);await loadSales()}catch(err){message(err.message,true)}}
 const adjust=e.target.closest('[data-adjust-sale]');if(adjust){const discount=prompt('New discount amount in GH₵:',String(activeSale?.discount??0));if(discount===null)return;const deliveryFee=prompt('New delivery fee in GH₵:',String(activeSale?.deliveryFee??0));if(deliveryFee===null)return;const reason=prompt('Reason for changing sale totals (required):');if(reason===null)return;if(!reason.trim()){message('A reason is required for financial adjustments.',true);return}try{await api(`/admin/pos/sales/${adjust.dataset.adjustSale}/adjustments`,{method:'PUT',body:JSON.stringify({discount,deliveryFee,reason:reason.trim()})});message('Sale totals adjusted and audit record created.');await viewSale(adjust.dataset.adjustSale);await loadSales()}catch(err){message(err.message,true)}}
 const regen=e.target.closest('[data-regenerate]');if(regen){await generateReceiptForSale(regen.dataset.regenerate)}
 const act=e.target.closest('[data-receipt-action]');if(act){try{await api(`/admin/pos/sales/${act.dataset.id}/receipt/${act.dataset.receiptAction}`,{method:'POST',body:JSON.stringify({reason:'Updated from Sales History'})});message('Receipt link status updated.');await viewSale(act.dataset.id);await loadSales()}catch(err){message(err.message,true)}}
 const audit=e.target.closest('[data-sale-audit]');if(audit){try{const d=await api(`/admin/pos/sales/${audit.dataset.saleAudit}/audit`);showModal('Audit history',`<pre style="white-space:pre-wrap;word-break:break-word;font-size:11px">${esc(JSON.stringify(d.audit,null,2))}</pre>`)}catch(err){message(err.message,true)}}
});
function showModal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden')};$('#modal').addEventListener('click',e=>{if(e.target.id==='modal'||e.target.closest('[data-close-modal]'))$('#modal').classList.add('hidden')});
async function renderOrders(){ $('#view').innerHTML=`<section class="panel"><h2>Import existing WhatsApp orders into sales history</h2><p class="sub">Imported orders retain their original item names/prices and are linked to the source order to prevent duplicate imports. No recorded payment is inferred from order status.</p><div class="filters"><input id="orderSearch" placeholder="Search order ID, customer, phone"><button id="loadOrders" class="btn primary">Refresh orders</button></div><div id="ordersTable" class="empty">Loading orders…</div></section>`;$('#loadOrders').onclick=loadOrders;$('#orderSearch').addEventListener('input',filterOrderRows);await loadOrders();}
async function loadOrders(){try{const d=await api('/admin/orders');orders=d.orders||[];filterOrderRows()}catch(e){$('#ordersTable').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function filterOrderRows(){const term=($('#orderSearch')?.value||'').toLowerCase();const rows=orders.filter(o=>[o.id,o.customerName,o.customerPhone].some(v=>String(v||'').toLowerCase().includes(term)));$('#ordersTable').innerHTML=rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Customer</th><th>Location</th><th>Total</th><th>Order status</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${esc(o.id)}</strong><div class="muted">${esc(o.createdAt)}</div></td><td>${esc(o.customerName)}<div class="muted">${esc(o.customerPhone)}</div></td><td>${esc(o.deliveryLocation)}${o.deliveryFeeStatus==='requires_confirmation'?'<div class="status pending">Delivery fee needs confirmation</div>':''}</td><td>${fmt(o.total)}</td><td>${esc(o.status)}</td><td><button class="btn teal" data-import-order="${esc(o.id)}" ${o.posSaleImported?'disabled':''}>${o.posSaleImported?'Already imported':'Import to sales'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No matching WhatsApp orders.</div>';}
$('#view').addEventListener('click',async e=>{const b=e.target.closest('[data-import-order]');if(!b)return;try{b.disabled=true;const r=await api(`/admin/pos/orders/${encodeURIComponent(b.dataset.importOrder)}/import`,{method:'POST',body:JSON.stringify({})});showModal('Order imported',`<p>Sale reference: <strong>${esc(r.sale.reference)}</strong></p><p>Total due: <strong>${fmt(r.sale.total)}</strong></p><p><a class="btn teal" href="${esc(r.receiptUrl||'#')}" target="_blank" rel="noopener">Open receipt</a></p><p class="muted">The order was imported without assuming that any payment had been received.</p>`);await loadOrders()}catch(err){message(err.message,true)}finally{b.disabled=false}});
async function renderMetadata(){await loadBase();$('#view').innerHTML=`<div class="grid"><section class="span-4"><div class="panel"><h2>Choose a published product</h2><p class="sub">Manage tags, SEO keywords, stock label, and independent Popular/Featured flags.</p><div class="field"><label>Search catalogue</label><input id="metaSearch" placeholder="Product name…"></div><div id="metaProducts" style="margin-top:10px;max-height:580px;overflow:auto"></div></div></section><section class="span-8"><div class="panel"><div class="between"><div><h2>Product tags & SEO</h2><p class="sub">Tags appear as crawlable product search links. Popular and Featured can be toggled independently.</p></div><span id="metaSelected" class="pill">Choose a product</span></div><form id="metaForm"><div class="grid"><div class="field span-12"><label>Product</label><input id="metaName" disabled></div><div class="field span-12"><label>Tags (comma separated)</label><input id="metaTags" placeholder="Black Suede, Wooden Finish, Modern Wardrobe"><small id="tagSuggestions" class="muted"></small></div><div class="field span-12"><label>SEO keywords (optional)</label><textarea id="metaKeywords" placeholder="wardrobe, wooden wardrobe, bedroom furniture"></textarea></div><div class="field span-6"><label>Stock status</label><select id="metaStock"><option value="in_stock">In Stock</option><option value="limited">Limited Stock</option><option value="out_of_stock">Out of Stock</option><option value="pre_order">Pre-order</option></select></div><div class="field span-6"><label>Publication status</label><select id="metaStatus"><option value="published">Published</option><option value="draft">Draft</option></select></div><label class="checkbox span-6"><input type="checkbox" id="metaPopular"> Popular product</label><label class="checkbox span-6"><input type="checkbox" id="metaFeatured"> Featured product</label><div class="span-12 row"><button class="btn primary" type="submit">Save product metadata</button><button class="btn" type="button" id="deleteTag">Remove unused/selected tag</button></div></div></form><div id="metaSaveResult" class="muted" style="margin-top:10px"></div></div><div class="panel"><div class="between"><div><h3>Existing tags</h3><p class="sub">Click a tag to copy its name into the selected product.</p></div><button class="btn" id="refreshTags">Refresh tags</button></div><div id="allTags"></div></div></section></div>`;
 const list=$('#metaProducts');function drawProducts(term=''){const items=catalogue.filter(p=>p.name.toLowerCase().includes(term.toLowerCase()));list.innerHTML=items.map(p=>`<button type="button" class="product-pick" style="width:100%;text-align:left;cursor:pointer;margin-bottom:6px" data-meta-product="${esc(p.id)}"><img src="${esc(p.featuredImage||p.images?.[0]||'/favicon.png')}" alt=""><span style="flex:1;min-width:0"><span class="name">${esc(p.name)}</span><span class="muted">${fmt(p.price)} · ${esc(p.categorySlug||'Uncategorized')}</span></span></button>`).join('')||'<div class="empty">No matching products.</div>';}drawProducts();$('#metaSearch').addEventListener('input',e=>drawProducts(e.target.value));$('#refreshTags').onclick=loadTags;await loadTags();$('#metaForm').addEventListener('submit',saveMetadata);$('#deleteTag').onclick=async()=>{const raw=prompt('Enter the exact tag name to remove from the tag library. This removes that tag from all linked products.');if(!raw)return;try{const d=await api('/admin/product-tags');const t=(d.tags||[]).find(x=>x.name.toLowerCase()===raw.toLowerCase());if(!t)throw new Error('Tag not found.');if(!confirm(`Remove “${t.name}” from all products?`))return;await api('/admin/product-tags/'+t.id,{method:'DELETE'});await loadTags();message('Tag removed from the library and product associations.')}catch(e){message(e.message,true)}};}
$('#view').addEventListener('click',e=>{const b=e.target.closest('[data-meta-product]');if(b)selectMetadataProduct(b.dataset.metaProduct)});
function selectMetadataProduct(id){const p=allProducts.find(x=>String(x.id)===String(id));if(!p)return;selectedProductId=String(p.id);$('#metaSelected').textContent=p.name;$('#metaName').value=p.name;$('#metaTags').value=(p.tags||[]).join(', ');$('#metaKeywords').value=p.seoKeywords||'';$('#metaStock').value=p.stockStatus||'in_stock';$('#metaStatus').value=p.publicationStatus||'published';$('#metaPopular').checked=!!p.isPopular;$('#metaFeatured').checked=!!p.isFeatured;const base=[p.name,p.description,p.categorySlug,...(p.colors||[]),...(p.sizes||[])].join(' ');const suggestions=[...new Set(base.toLowerCase().match(/[a-z0-9-]{3,}/g)||[])].filter(w=>!['with','the','and','for','from','that','this','your','goodlucks','goods'].includes(w)).slice(0,20);$('#tagSuggestions').innerHTML='Suggestions: '+suggestions.map(t=>`<button type="button" class="tag" data-suggest-tag="${esc(t)}">${esc(t)}</button>`).join('');$('#metaSaveResult').textContent='';}
$('#view').addEventListener('click',e=>{const b=e.target.closest('[data-suggest-tag]');if(!b)return;const old=$('#metaTags').value.split(',').map(x=>x.trim()).filter(Boolean);if(!old.some(x=>x.toLowerCase()===b.dataset.suggestTag.toLowerCase()))old.push(b.dataset.suggestTag);$('#metaTags').value=old.join(', ')});
async function saveMetadata(e){e.preventDefault();if(!selectedProductId){message('Choose a product first.',true);return}const tags=$('#metaTags').value.split(',').map(t=>t.trim()).filter(Boolean);try{const r=await api(`/admin/products/${selectedProductId}/metadata`,{method:'PUT',body:JSON.stringify({tags,seoKeywords:$('#metaKeywords').value,stockStatus:$('#metaStock').value,publicationStatus:$('#metaStatus').value,isPopular:$('#metaPopular').checked,isFeatured:$('#metaFeatured').checked})});$('#metaSaveResult').textContent='Saved successfully.';await loadBase();selectMetadataProduct(selectedProductId);message('Product tags and SEO metadata saved.');}catch(e){message(e.message,true)}}
async function loadTags(){try{const d=await api('/admin/product-tags');$('#allTags').innerHTML=(d.tags||[]).map(t=>`<button type="button" class="tag" data-suggest-tag="${esc(t.name)}">${esc(t.name)} <small>(${t.productCount})</small></button>`).join('')||'<span class="muted">No tags have been created yet.</span>'}catch(e){$('#allTags').textContent=e.message}}
async function renderDrafts(){await loadBase();const d=await api('/admin/drafts');drafts=d.drafts||[];selectedDraftId='';draftImages=[];$('#view').innerHTML=`<div class="grid"><section class="span-4"><div class="panel"><div class="between"><div><h2>Drafts</h2><p class="sub">Drafts are private and excluded from public catalogues and search indexing.</p></div><button class="btn teal" id="newDraft">+ New draft</button></div><div id="draftList"></div></div></section><section class="span-8"><div class="panel"><div class="between"><div><h2 id="draftHeading">Create draft</h2><p class="sub">Save incomplete details and continue later. Publishing validates the required fields.</p></div><span class="pill">Private</span></div><form id="draftForm" class="grid"><div class="field span-6"><label>Product name</label><input id="draftName" maxlength="255" placeholder="Product name"></div><div class="field span-3"><label>Price (GH₵)</label><input id="draftPrice" type="number" min="0" step="0.01" value="0"></div><div class="field span-3"><label>Discount price</label><input id="draftDiscount" type="number" min="0" step="0.01"></div><div class="field span-6"><label>Category</label><select id="draftCategory">${categoryOptions()}</select></div><div class="field span-6"><label>Subcategory</label><select id="draftSubcategory"><option value="">Choose subcategory…</option></select></div><div class="field span-12"><label>Description</label><textarea id="draftDescription"></textarea></div><div class="field span-12"><label>SEO keywords</label><textarea id="draftKeywords"></textarea></div><div class="field span-12"><label>Tags (comma separated)</label><input id="draftTags"></div><div class="field span-12"><label>Product images (max 15)</label><input id="draftImageFiles" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple><div class="row"><button type="button" class="btn" id="uploadDraftImages">Upload selected images</button><button type="button" class="btn" id="clearDraftImages">Clear image list</button></div><div id="draftImagePreview" class="muted">No images uploaded.</div></div><div class="field span-12"><label>Variant JSON (optional; variant images must be uploaded first)</label><textarea id="draftVariants" placeholder='[{"name":"Cream","images":["/api/uploads/products/image.jpg"],"isAvailable":true}]'></textarea></div><div class="span-12 row"><button class="btn primary" type="submit">Save draft</button><button class="btn teal" type="button" id="publishDraft" disabled>Validate & publish</button><button class="btn" type="button" id="previewDraft" disabled>Private preview</button></div></form><div id="draftResult" style="margin-top:10px"></div></div></section></div>`;
 drawDrafts();$('#newDraft').onclick=()=>{selectedDraftId='';draftImages=[];$('#draftHeading').textContent='Create draft';$('#draftForm').reset();$('#draftPrice').value='0';$('#draftImagePreview').textContent='No images uploaded.';$('#publishDraft').disabled=true;$('#previewDraft').disabled=true;};$('#draftCategory').addEventListener('change',()=>fillDraftSubcategories());$('#draftForm').addEventListener('submit',saveDraft);$('#uploadDraftImages').onclick=uploadDraftImages;$('#clearDraftImages').onclick=()=>{draftImages=[];paintDraftImages()};$('#publishDraft').onclick=publishDraft;$('#previewDraft').onclick=previewDraft;}
function drawDrafts(){const box=$('#draftList');if(!box)return;box.innerHTML=drafts.map(d=>`<div class="product-pick" style="margin-bottom:7px"><img src="${esc(d.featuredImage||'/favicon.png')}" alt=""><div style="flex:1;min-width:0"><span class="name">${esc(d.name||'Untitled draft')}</span><span class="muted">Updated ${esc(d.createdAt||'')}</span></div><button class="btn" data-edit-draft="${esc(d.id)}">Edit</button></div>`).join('')||'<div class="empty">No saved drafts yet.</div>';}
$('#view').addEventListener('click',e=>{const b=e.target.closest('[data-edit-draft]');if(b)editDraft(b.dataset.editDraft)});
async function editDraft(id){try{const d=(await api('/admin/drafts')).drafts.find(x=>String(x.id)===String(id));if(!d)throw new Error('Draft not found');selectedDraftId=String(d.id);draftImages=[...(d.images||[])];$('#draftHeading').textContent='Edit draft #'+id;$('#draftName').value=d.name==='New Draft'?'':d.name;$('#draftPrice').value=d.price||0;$('#draftDiscount').value=d.discountPrice??'';$('#draftCategory').value=d.categorySlug||'';fillDraftSubcategories(d.subcategorySlug);$('#draftDescription').value=d.description||'';$('#draftKeywords').value=d.seoKeywords||'';$('#draftTags').value=(d.tags||[]).join(', ');$('#draftVariants').value=JSON.stringify((d.variants||[]).map(v=>({...v,images:v.images||[]})),null,2);$('#publishDraft').disabled=false;$('#previewDraft').disabled=false;paintDraftImages();}catch(e){message(e.message,true)}}
function fillDraftSubcategories(selected=''){const c=categories.find(c=>c.slug===$('#draftCategory').value);$('#draftSubcategory').innerHTML='<option value="">No subcategory</option>'+(c?.subcategories||[]).map(s=>`<option value="${esc(s.slug)}" ${s.slug===selected?'selected':''}>${esc(s.name)}</option>`).join('')}
function paintDraftImages(){const box=$('#draftImagePreview');if(!box)return;box.innerHTML=draftImages.length?`<div class="row">${draftImages.map((src,i)=>`<div style="position:relative;width:80px"><img src="${esc(src)}" alt="" style="width:80px;height:65px;object-fit:cover;border-radius:7px;border:1px solid var(--line)"><button type="button" class="btn danger" style="margin-top:4px;width:100%;padding:5px" data-remove-draft-image="${i}">Remove</button></div>`).join('')}</div><div class="muted" style="margin-top:6px">${draftImages.length}/15 images selected; first image is the primary product image.</div>`:'No images uploaded.'}
$('#view').addEventListener('click',e=>{const b=e.target.closest('[data-remove-draft-image]');if(b){draftImages.splice(+b.dataset.removeDraftImage,1);paintDraftImages()}});
async function uploadDraftImages(){
 const files=Array.from($('#draftImageFiles').files||[]);if(!files.length){message('Choose one or more image files first.',true);return}
 if(draftImages.length+files.length>15){message('A product can have a maximum of 15 images.',true);return}
 const b=$('#uploadDraftImages');b.disabled=true;let completed=0;
 try{
   for(const file of files){
     const fd=new FormData();fd.append('kind','product');fd.append('currentCount',String(draftImages.length));fd.append('image',file);
     const r=await api('/admin/upload-image',{method:'POST',body:fd});
     const one=r.image||r.imageUrl||r.image_url||r.url||r.path||(Array.isArray(r.images)?r.images[0]:null);
     const many=Array.isArray(r.images)?r.images:[];const added=(many.length?many:[one]).filter(Boolean).map(String);
     if(!added.length)throw new Error(`The server did not return a saved path for ${file.name}.`);
     for(const src of added){if(!draftImages.includes(src))draftImages.push(src)}
     if(draftImages.length>15)throw new Error('The saved image count would exceed the 15-image maximum.');
     completed++;paintDraftImages();
   }
   $('#draftImageFiles').value='';message(`${completed} image(s) uploaded. Save the draft to keep these image associations.`);
 }catch(e){message(`${completed} image(s) uploaded before the error: ${e.message} Other draft fields and completed image paths remain in the form.`,true)}
 finally{b.disabled=false}
}
async function saveDraft(e){e.preventDefault();const data={name:$('#draftName').value,price:$('#draftPrice').value,discountPrice:$('#draftDiscount').value,categorySlug:$('#draftCategory').value,subcategorySlug:$('#draftSubcategory').value,description:$('#draftDescription').value,seoKeywords:$('#draftKeywords').value,tags:$('#draftTags').value.split(',').map(s=>s.trim()).filter(Boolean),images:draftImages};try{const raw=$('#draftVariants').value.trim();if(raw)data.variants=JSON.parse(raw);const url=selectedDraftId?'/admin/drafts/'+selectedDraftId:'/admin/drafts';const r=await api(url,{method:selectedDraftId?'PUT':'POST',body:JSON.stringify(data)});selectedDraftId=String((r.draft||{}).id||selectedDraftId);$('#draftHeading').textContent='Edit draft #'+selectedDraftId;$('#publishDraft').disabled=false;$('#previewDraft').disabled=false;const d=await api('/admin/drafts');drafts=d.drafts||[];drawDrafts();message('Draft saved. It remains hidden from public storefront and search engines.')}catch(e){message('Draft not saved: '+e.message,true)}}
async function publishDraft(){if(!selectedDraftId){message('Save the draft before publishing.',true);return}if(!confirm('Publish this product to the public catalogue?'))return;try{const d=await api('/admin/drafts/'+selectedDraftId+'/publish',{method:'POST',body:JSON.stringify({})});message('Product published successfully: '+d.product.name);await renderDrafts()}catch(e){message(e.message,true)}}
async function previewDraft(){if(!selectedDraftId)return;try{const d=await api('/admin/drafts/'+selectedDraftId+'/preview');showModal('Private draft preview',`<div class="detail-grid"><div class="metric"><small>Name</small><strong>${esc(d.preview.name)}</strong></div><div class="metric"><small>Price</small><strong>${fmt(d.preview.price)}</strong></div><div class="metric"><small>Images</small><strong>${esc(d.preview.images.length)}</strong></div></div><p><strong>Category:</strong> ${esc(d.preview.categorySlug||'Not set')}</p><p><strong>Description:</strong><br>${esc(d.preview.description||'Not set')}</p><p><strong>Tags:</strong> ${esc((d.preview.tags||[]).join(', ')||'None')}</p><p class="muted">This preview is visible only to an authenticated administrator.</p>`)}catch(e){message(e.message,true)}}
async function renderSubcategories(){await loadBase();const subs=subcategoryList();$('#view').innerHTML=`<section class="panel"><h2>Edit subcategories</h2><p class="sub">Edit existing subcategories without deleting them. Existing product associations are retained; if a subcategory is moved to another parent, associated products are updated within the same transaction.</p><div class="grid"><div class="field span-4"><label>Existing subcategory</label><select id="subPick"><option value="">Choose a subcategory…</option>${subs.map(s=>`<option value="${esc(s.id)}">${esc(s.parentCategoryName)} → ${esc(s.name)}</option>`).join('')}</select></div><div class="field span-8"><label> </label><div class="muted">Editing here updates the current Categories data. Unique slugs are required.</div></div></div><form id="subForm" class="grid" style="margin-top:15px"><div class="field span-4"><label>Name *</label><input id="subName" required maxlength="150"></div><div class="field span-4"><label>Slug *</label><input id="subSlug" required maxlength="150"></div><div class="field span-4"><label>Parent category</label><select id="subParent">${categoryOptions()}</select></div><div class="field span-6"><label>Description</label><textarea id="subDescription"></textarea></div><div class="field span-6"><label>SEO meta description</label><textarea id="subMeta"></textarea></div><div class="field span-12"><label>Image path or URL (optional)</label><input id="subImage" placeholder="Existing image path or URL"></div><div class="span-12"><button class="btn primary" type="submit">Save subcategory</button></div></form></section>`;$('#subPick').addEventListener('change',()=>{const s=subs.find(x=>String(x.id)===$('#subPick').value);selectedSubcategoryId=s?String(s.id):'';$('#subName').value=s?.name||'';$('#subSlug').value=s?.slug||'';$('#subParent').value=s?.parentCategorySlug||'';$('#subDescription').value=s?.description||'';$('#subMeta').value=s?.metaDescription||'';$('#subImage').value=s?.image||''});$('#subForm').addEventListener('submit',async e=>{e.preventDefault();if(!selectedSubcategoryId){message('Choose a subcategory first.',true);return}try{await api('/admin/subcategories/'+selectedSubcategoryId,{method:'PUT',body:JSON.stringify({name:$('#subName').value,slug:$('#subSlug').value,description:$('#subDescription').value,metaDescription:$('#subMeta').value,image:$('#subImage').value,parentCategorySlug:$('#subParent').value})});await loadBase();message('Subcategory updated without recreating it.');await renderSubcategories()}catch(err){message(err.message,true)}})}
(async()=>{try{await loadBase();render()}catch(e){message('Unable to load admin tools: '+e.message,true)}})();
</script></body></html>
